#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
# Integration-test runner for the DAV layer (Makefile-independent).
#
#   run.sh            run both suites below, one after the other, tearing each stack down
#   run.sh dav        only dav.test.mjs, against the simple instance of this script
#   run.sh store      only {contacts,collections,import,calendar}.test.mjs, against the production-plugin stack of
#                     stack.py (Radicale with backend/plugin, rights generated by the real backend; accounts
#                     alice, bob, agent-1; ports 15430-15449; RADUI_IT_SKIP_SCALE=1 skips the 2,000-contact test)
#   run.sh up         start the simple instance only (prints the environment to export)
#   run.sh down       stop and remove the simple instance
#
# Throwaway only: current user, 127.0.0.1, temporary directory carrying a
# marker file. Accounts alice, bob and agent-1 get random passwords written to
# <dir>/passwords (mode 600, never printed). Rights: every account owns its
# principal and its collections (letters rwDO); permit_delete_collection and
# permit_overwrite_collection are off, so only D/O holders may delete or
# overwrite a collection, as in a locked-down production setup; bob additionally holds a read-write grant (rwl: the lower-case l
# denies PROPPATCH) on alice/shared-rw and a read-only grant on alice/shared-ro.
#
# Environment (all optional):
#   RADICALE_BIN         radicale executable (default: radicale, or .env.local)
#   RADUI_DAV_PORT       listen port (default 15270; keep within 15270-15279)
#   RADUI_DAV_DIR        state directory (default <repo>/.throwaway/dav-it-<port>)
#   RADUI_BCRYPT_COST    bcrypt rounds for the test accounts (default 5)
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE/../../.." && pwd)"

if [ -z "${RADICALE_BIN:-}" ] && [ -f "$REPO/.env.local" ]; then
  RADICALE_BIN="$(grep -E '^RADICALE_BIN=' "$REPO/.env.local" | head -n1 | cut -d= -f2- | tr -d '"')"
fi
RADICALE_BIN="${RADICALE_BIN:-radicale}"
PORT="${RADUI_DAV_PORT:-15270}"
COST="${RADUI_BCRYPT_COST:-5}"
DIR="$(realpath -m "${RADUI_DAV_DIR:-$REPO/.throwaway/dav-it-$PORT}")"
MARKER="$DIR/.radui-throwaway"
PIDFILE="$DIR/radicale.pid"
CONF="$DIR/config"

die() { echo "run.sh: $*" >&2; exit 1; }

case "$PORT" in
  1527[0-9]) ;;
  *) die "port $PORT outside the throwaway range 15270-15279" ;;
esac
case "$DIR" in
  /|/var/lib|/var/lib/*|/etc|/etc/*|/usr|/usr/*|/home|"$HOME") die "refusing state dir $DIR" ;;
esac

running_pid() {
  local pid
  [ -f "$PIDFILE" ] || return 1
  pid="$(cat "$PIDFILE")"
  [[ "$pid" =~ ^[0-9]+$ ]] || return 1
  tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -qF -- "$CONF" || return 1
  echo "$pid"
}

pick_python() {
  local py bin
  bin="$(command -v "$RADICALE_BIN" 2>/dev/null || echo "$RADICALE_BIN")"
  for py in python3 "$(dirname "$bin")/python"; do
    if "$py" -c 'import bcrypt' >/dev/null 2>&1; then echo "$py"; return 0; fi
  done
  return 1
}

write_accounts() {
  local py
  py="$(pick_python)" || die "no python with the bcrypt module found"
  DIR="$DIR" COST="$COST" "$py" - <<'PYEOF'
import bcrypt, os, secrets
d, cost = os.environ["DIR"], int(os.environ["COST"])
users, plain = [], []
for name in ("alice", "bob", "agent-1"):
    pw = secrets.token_urlsafe(18)
    h = bcrypt.hashpw(pw.encode(), bcrypt.gensalt(rounds=cost)).decode()
    users.append("%s:%s" % (name, h))
    plain.append("%s:%s" % (name, pw))
for fn, rows in (("users", users), ("passwords", plain)):
    fd = os.open(os.path.join(d, fn), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as fh:
        fh.write("\n".join(rows) + "\n")
PYEOF
}

write_config() {
  mkdir -p "$DIR/collections"
  cat > "$DIR/rights" <<'RIGHTSEOF'
# First matching section wins.
[root]
user: .+
collection:
permissions: R

[bob-readwrite-grant]
user: bob
collection: alice/shared-rw
permissions: rwl

[bob-readonly-grant]
user: bob
collection: alice/shared-ro
permissions: r

[principal]
user: .+
collection: {user}
permissions: RW

[own-collections]
user: .+
collection: {user}/[^/]+
permissions: rwDO
RIGHTSEOF
  cat > "$CONF" <<CONFEOF
[server]
hosts = 127.0.0.1:$PORT

[auth]
type = htpasswd
htpasswd_filename = $DIR/users
htpasswd_encryption = bcrypt
delay = 0

[rights]
type = from_file
file = $DIR/rights
permit_delete_collection = False
permit_overwrite_collection = False

[storage]
filesystem_folder = $DIR/collections

[logging]
level = warning
CONFEOF
}

cmd_up() {
  local pid i code avail
  avail="$(free -m | awk '/^Mem:/ {print $7}')"
  [ "${avail:-0}" -ge 2048 ] || die "less than 2 GB memory available ($avail MB)"
  command -v "$RADICALE_BIN" >/dev/null 2>&1 || [ -x "$RADICALE_BIN" ] || die "radicale binary not found (set RADICALE_BIN)"
  if running_pid >/dev/null; then die "already running (pid $(running_pid))"; fi
  if [ -e "$DIR" ] && [ ! -f "$MARKER" ]; then die "$DIR exists and is not a throwaway dir"; fi
  if (exec 3<>"/dev/tcp/127.0.0.1/$PORT") 2>/dev/null; then die "port $PORT is in use"; fi
  rm -rf -- "$DIR"
  (umask 077; mkdir -p "$DIR"; : > "$MARKER"; write_accounts)
  write_config
  nohup "$RADICALE_BIN" --config "$CONF" </dev/null >"$DIR/radicale.log" 2>&1 &
  pid=$!
  echo "$pid" > "$PIDFILE"
  for i in $(seq 1 100); do
    kill -0 "$pid" 2>/dev/null || { tail -n 20 "$DIR/radicale.log" >&2; die "radicale exited during startup"; }
    code="$(curl -s -o /dev/null -m 3 -w '%{http_code}' -X PROPFIND "http://127.0.0.1:$PORT/" 2>/dev/null || true)"
    if [ -n "$code" ] && [ "$code" != "000" ]; then
      echo "throwaway radicale up on 127.0.0.1:$PORT (pid $pid)"
      echo "export RADUI_TEST_RADICALE=http://127.0.0.1:$PORT"
      echo "export RADUI_TEST_PASSWORDS_FILE=$DIR/passwords"
      return 0
    fi
    sleep 0.2
  done
  kill "$pid" 2>/dev/null || true
  die "radicale did not become ready within 20 s"
}

cmd_down() {
  local pid i
  if pid="$(running_pid)"; then
    kill "$pid" 2>/dev/null || true
    for i in $(seq 1 50); do kill -0 "$pid" 2>/dev/null || break; sleep 0.1; done
    if kill -0 "$pid" 2>/dev/null; then kill -9 "$pid" 2>/dev/null || true; fi
  fi
  if [ -f "$MARKER" ]; then rm -rf -- "$DIR"; fi
  echo "throwaway radicale down"
}

case "${1:-test}" in
  up) cmd_up ;;
  down) cmd_down ;;
  dav|test|store)
    cd "$REPO"
    if [ "${1:-test}" != store ]; then
      trap cmd_down EXIT
      cmd_up >/dev/null
      RADUI_TEST_RADICALE="http://127.0.0.1:$PORT" RADUI_TEST_PASSWORDS_FILE="$DIR/passwords" \
        env -u RADUI_TEST_PROD_RADICALE timeout 600 node --test tests/integration/dav/dav.test.mjs
      cmd_down
      trap - EXIT
    fi
    if [ "${1:-test}" != dav ]; then
      env -u RADUI_TEST_RADICALE -u RADUI_TEST_PASSWORDS_FILE python3 tests/integration/dav/stack.py run -- \
        timeout 1500 node --test tests/integration/dav/contacts.test.mjs tests/integration/dav/collections.test.mjs tests/integration/dav/import.test.mjs tests/integration/dav/calendar.test.mjs
    fi
    ;;
  *) echo "usage: $0 [test|dav|store|up|down]" >&2; exit 2 ;;
esac
